function navigation(activeTab){
  return navGroups.map(group=>`<div class="nav-group">${group.label?`<div class="nav-group-title">${group.label}</div>`:''}${group.items.map(id=>{const [,icon,name]=tabs.find(item=>item[0]===id);return `<button data-tab="${id}" class="${activeTab===id?'active':''}"><span>${icon}</span>${name}</button>`;}).join('')}</div>`).join('');
}
const row=(a,b)=>`<div class="fundrow"><span>${a}</span><b>${b}</b></div>`;
const tag=(x,warn=false)=>`<span class="tag ${warn?'warn':''}">${x}</span>`;
const panel=(title,body,side='')=>`<section class="panel"><div class="panelhead"><h2>${title}</h2>${side}</div>${body}</section>`;
const check=(id,label,checked=false)=>`<label class="check"><input id="${id}" name="${id}" type="checkbox" ${checked?'checked':''}>${label}</label>`;
export function field(k,label,value,help='',type='number'){
  return `<div class="field"><label for="${k}">${label}${type==='number'?' / 元':''}</label><input id="${k}" name="${k}" type="${type}" ${type==='number'?'min="0" max="100000000" step="0.01"':'maxlength="40"'} value="${type==='number'?(value/100).toFixed(2):esc(value)}" required>${help?`<small>${help}</small>`:''}</div>`;
}
function select(id,label,values,current){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${values.map(([v,n])=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${n}</option>`).join('')}</select></div>`;}
function optionalMoneyField(id,label,value,help=''){return `<div class="field"><label for="${id}">${label} / 元</label><input id="${id}" name="${id}" type="number" min="0" max="100000000" step="0.01" value="${value===null?'':(value/100).toFixed(2)}" placeholder="留空默认按基本工资"><small>${help}</small></div>`;}
function percentField(id,label,value){return `<div class="field suffix-field"><label for="${id}">${label}</label><div><input id="${id}" name="${id}" type="number" min="0" max="100" step="0.01" value="${(value/100).toFixed(2)}" required><span>%</span></div></div>`;}
function lawfulFields(prefix,values,annual=false){
  return `<div class="lawful-grid">${lawfulKeys.map(key=>{const meta=lawfulTypes[key],id=`${prefix}law_${key}`,enabled=(values?.[key]??0)>0;return `<div class="lawful-item ${enabled?'selected':''}"><label class="lawful-check"><input name="${prefix}law_enabled_${key}" type="checkbox" data-law-toggle="${id}" ${enabled?'checked':''}><span><b>${meta.name}</b><small>${meta.help}</small></span></label><div class="field"><label for="${id}">${annual?'全年':'本月'}可扣金额 / 元</label><input id="${id}" name="${id}" type="number" min="0" max="100000000" step="0.01" value="${((values?.[key]??0)/100).toFixed(2)}" ${enabled?'':'disabled'} required></div></div>`;}).join('')}</div>`;
}
function flowSteps(step,canResult,label){return `<div class="flow-head"><div><span class="eyebrow">当前测算</span><b>${label}</b></div><div class="flow-steps"><button type="button" data-flow-step="1" class="${step===1?'active':''}"><i>1</i>填写金额与扣除</button><span></span><button type="button" data-flow-step="2" class="${step===2?'active':''}" ${canResult?'':'disabled'}><i>2</i>查看计算结果</button></div></div>`;}
function card(label,value,note,dark=false){return `<div class="card ${dark?'dark':''}"><div class="label">${label}</div><div class="big">${label==='待确认项目数'?value/100+' 项':yuan(value)}</div><div class="note">${note}</div></div>`;}
function warning(s){
  const c=coverage(s),warnings=[];
  if(s.mode==='monthly'&&c.missing.length)warnings.push(`未填月份：${c.missing.join('、')}月`);
  if(s.mode==='quick'&&s.quick.source==='monthly'&&c.missing.length)warnings.push(`汇总截止月内未填：${c.missing.join('、')}月`);
  if(s.mode==='quick'&&!s.quick.confirmed)warnings.push('年度精算尚未保存并确认');
  if(c.pendingBaseline)warnings.push(`${c.pendingBaseline}项基准扣除待分类或确认`);
  if(!s.scope)warnings.push('尚未确认产品适用范围');
  if(!warnings.length)return '';
  return `<div class="banner"><div><b>暂不生成全年推荐</b><br>${warnings.join('；')}。缺失数据不按0计算。</div><button data-tab="${c.pendingBaseline?'deductions':!s.scope?'settings':s.mode==='quick'?'quick':'monthly'}">去补齐</button></div>`;
}
function footer(){return `<footer class="footer"><span>中国内地居民 · 自年初同一单位普通工资场景。测算仅供参考，实际以适用政策及扣缴申报为准。</span><span>数据仅存本机 · ${VERSION}</span></footer>`;}
