  return `<div class="discovery-progress">${names.map((name,i)=>`<button type="button" data-finder-step="${i+1}" class="${step===i+1?'active':step>i+1?'done':''}" ${i+1>step?'disabled':''}><i>${i+1}</i><span>${name}</span></button>`).join('<b></b>')}</div>`;
