function finderPolicyBlock(title,kicker,description,body,note=''){
  return `<section class="finder-policy-block"><div class="finder-policy-head"><span>${kicker}</span><div><h3>${title}</h3><p>${description}</p></div></div><div class="finder-fields">${body}</div>${note?`<div class="finder-note">${note}</div>`:''}</section>`;
}
function finderForm(step,title,intro,briefGuide,blocks){
  return `${finderProgress(step)}<section class="panel discovery-form"><div class="discovery-kicker">第${step}步，共4步</div><h2>${title}</h2><p class="sub">${intro}</p><form id="finderForm"><section class="finder-module finder-brief-module"><div class="finder-module-head"><i>01</i><div><b>情况简要问答</b><small>用日常语言描述情况，确认后由本机智能识别并预填表格。</small></div><span>AI 智能预填</span></div><div class="finder-brief-layout"><div class="finder-brief-guide"><b>填写指引</b><p>${briefGuide}</p><ul><li>只写政策判断所需的信息，不填写姓名、证件号或病历。</li><li>识别在当前浏览器完成，文本不会上传；预填后仍需逐项核对。</li></ul></div><div class="finder-brief-input"><label for="finderBrief">请简要说明你的情况</label><textarea id="finderBrief" name="finderBrief" rows="5" maxlength="600" placeholder="请按左侧指引，用一两句话描述……"></textarea><label class="finder-ai-confirm"><input id="finderBriefConfirm" type="checkbox"><span><b>我已填写完毕，确认由 AI 智能识别并自动填充下方表格</b><small>勾选后立即执行；识别结果会以高亮标注。</small></span></label><div id="finderBriefStatus" class="finder-brief-status">尚未执行识别，也可以直接填写下方表格。</div></div></div></section><section class="finder-module finder-table-module"><div class="finder-module-head"><i>02</i><div><b>核对并完善结构化表格</b><small>同一页面按政策项目分区，逐项确认资格、人数、月份和分配方式。</small></div><span>人工确认</span></div><div class="finder-policy-stack">${blocks}</div></section><div class="submit-zone"><div><b>回答只保存在当前浏览器</b><span>智能预填只减少录入工作，最终仍以你确认并保存的结构化表格为准。</span></div><div class="actions">${step>1?`<button type="button" data-finder-step="${step-1}">← 上一步</button>`:''}<button class="primary" type="submit">${step===4?'查看发现结果':'保存并继续 →'}</button></div></div></form></section>`;
}
function estimateFinderSaving(s,match,index){
  if(match.status!=='likely'||!match.ledgerDraft)return null;
  try{
    const base=calculate(s);if(base.finalTax===null)return null;
    const next=structuredClone(s),candidate={id:`finder-preview-${index}`,...match.ledgerDraft,usage:'baseline',timing:'annual',confirmed:true};
    next.deductions.push(candidate);const after=calculate(next);return after.finalTax===null?null:Math.max(0,base.finalTax-after.finalTax);
  }catch{return null;}
}
function finderResultCard(s,match,index){
  const statusName={likely:'建议核对',needs_info:'信息不足',conflict:'存在冲突',not_matched:'当前未发现'}[match.status];
  const saving=estimateFinderSaving(s,match,index),canApply=match.status==='likely'&&match.ledgerDraft;
  const details=[...match.reasons.map(x=>`<li>${esc(x)}</li>`),...match.missingChecks.map(x=>`<li class="pending">待确认：${esc(x)}</li>`),...match.conflicts.map(x=>`<li class="conflict">${esc(x)}</li>`)].join('');
  const action=canApply?`<button class="primary" data-finder-apply="${index}">带入专项扣除台账</button>`:match.existingId?`<button data-finder-existing="${esc(match.existingId)}">查看现有台账记录</button>`:'';
  return `<article class="suggestion-card status-${match.status}"><div class="suggestion-head"><div><span class="suggestion-status">${statusName}</span><h3>${esc(match.name)}</h3></div>${match.estimatedDeductionCents?`<div class="suggestion-amount"><small>预计年度可扣除</small><b>${yuan(match.estimatedDeductionCents)}</b></div>`:''}</div>${details?`<ul>${details}</ul>`:'<p class="sub">根据当前回答暂未发现匹配条件。</p>'}${match.estimatedDeductionCents?`<div class="impact-row"><span>按当前收入单项估算税额影响</span><b>${saving===null?'补齐全年收入后测算':`预计少缴 ${yuan(saving)}`}</b></div>`:''}<div class="suggestion-foot"><a href="${match.sourceUrl}" target="_blank" rel="noopener">查看政策依据 ↗</a>${action}</div></article>`;
}
function finderResults(s){
  const result=findPolicyMatches(s.finder,s.deductions),matches=result.matches.map((m,i)=>({...m,_index:i}));
  const groups=[['建议核对',matches.filter(x=>x.status==='likely')],['需要补充或处理冲突',matches.filter(x=>['needs_info','conflict'].includes(x.status))],['当前未发现',matches.filter(x=>x.status==='not_matched')]];
  const likely=groups[0][1].length,attention=groups[1][1].length,total=matches.filter(x=>x.status==='likely').reduce((sum,x)=>sum+x.estimatedDeductionCents,0);
  return `${finderProgress(5)}<div class="discovery-summary"><div><span>建议核对</span><b>${likely} 项</b></div><div><span>需要补充</span><b>${attention} 项</b></div><div><span>候选年度扣除合计</span><b>${yuan(total)}</b><small>仅为各候选项目合计，不等于少缴税额</small></div></div><div class="intro"><b>系统只完成初步发现。</b> 请逐项核对适用月份、家庭分配、历史享受期限和申报材料；确认后再带入台账。大病医疗仅在年度汇算处理。</div>${groups.map(([name,list])=>`<section class="finder-group"><div class="panelhead"><h2>${name}</h2>${tag(`${list.length}项`,name!=='建议核对')}</div>${list.length?`<div class="suggestion-grid">${list.map(x=>finderResultCard(s,x,x._index)).join('')}</div>`:'<div class="empty">暂无项目</div>'}</section>`).join('')}<div class="panel discovery-actions"><div><b>需要修改回答？</b><p class="sub">重新核对不会覆盖已经保存的专项扣除台账。</p></div><div class="actions"><button data-finder-step="1">重新检查回答</button><button data-tab="deductions">查看专项扣除申报台账</button></div></div><div class="helper">规则版本 ${esc(result.ruleVersion)}，政策核对日期 ${POLICY_AS_OF}。推荐结果只基于本机回答和已录收入，不代表税务机关已经确认资格。</div>`;
}
function policyFinder(s){
  const f=s.finder,a=f.answers,monthPair=(prefix,label)=>`${select(`${prefix}Start`,`${label}起始月份`,finderMonths,a[`${prefix}Start`])}${select(`${prefix}End`,`${label}结束月份`,finderMonths,a[`${prefix}End`])}`;
  if(f.step===5)return finderResults(s);
  if(f.step===1)return finderForm(
    1,'子女与照护','先用一段话概括子女年龄和就学情况，再按政策项目分别核对。每名子女的适用月份与扣除比例都可以继续修改。',
    '简要说明子女的年龄、人数、学历或就学阶段、适用起止月份，以及由本人按100%还是与配偶各按50%扣除。例如：“有1名2岁孩子，全年由我100%扣除；另有1名读小学的孩子，9月起与配偶各扣50%。”',
    finderPolicyBlock('婴幼儿照护','政策项目 A','核对3岁以下婴幼儿的人数、适用月份和父母分配方式。',`${select('baby','是否有3岁以下婴幼儿',finderYN,a.baby)}${select('babyCount','婴幼儿人数',Array.from({length:5},(_,i)=>[i+1,`${i+1}名`]),a.babyCount)}${select('babyShare','本人计划扣除比例',[[100,'100%'],[50,'50%']],a.babyShare)}${monthPair('baby','婴幼儿照护')}`,'父母可选择一方按100%扣除，或双方分别按50%扣除。')+
    finderPolicyBlock('子女教育','政策项目 B','核对接受学前教育或全日制学历教育子女的人数、月份和分配方式。',`${select('child','是否有处于符合条件教育阶段的子女',finderYN,a.child)}${select('childCount','符合条件的子女人数',Array.from({length:5},(_,i)=>[i+1,`${i+1}名`]),a.childCount)}${select('childShare','本人计划扣除比例',[[100,'100%'],[50,'50%']],a.childShare)}${monthPair('child','子女教育')}`,'同一子女同月不能同时享受婴幼儿照护和子女教育。')
  );
  if(f.step===2)return finderForm(
    2,'赡养老人','先概括被赡养人的年龄与家庭情况，再分别确认资格和家庭分摊。',
    '简要说明父母或其他符合条件被赡养人的年龄、你是否为独生子女、非独生子女时每月分摊金额及适用月份。例如：“父母均已满60岁，我不是独生子女，约定每月由我分摊1500元，全年适用。”',
    finderPolicyBlock('资格与适用月份','政策项目 A','确认是否存在符合条件且年满60周岁的被赡养人。',`${select('elder','是否赡养符合条件且年满60周岁的老人',finderYN,a.elder)}${monthPair('elder','赡养老人')}`)+
    finderPolicyBlock('家庭身份与分摊','政策项目 B','根据独生子女身份或家庭协议确认本人扣除金额。',`${select('sole','是否为独生子女',finderYN,a.sole)}${field('elderShare','非独生子女本人每月分摊金额',a.elderShare,'个人每月不超过1500元；独生子女无需修改。')}`,'非独生子女可均摊、约定分摊或由被赡养人指定分摊；约定或指定分摊需留存书面协议。')
  );
  if(f.step===3)return finderForm(
    3,'住房情况','先描述当前租住和首套住房贷款情况，再分区核对两类政策及互斥选择。',
    '简要说明是否在主要工作城市租房、本人或配偶当地是否有住房、租金扣除档，以及是否偿还首套房贷、已享受月份和本人扣除比例。例如：“在上海租房且夫妻当地无房，全年适用1500元档；同时有首套房贷，拟选择租金扣除。”',
    finderPolicyBlock('住房租金','政策项目 A','核对租房事实、主要工作城市住房情况、档位和适用月份。',`${select('rent','是否在主要工作城市实际租房',finderYN,a.rent)}${select('cityHousing','本人或配偶在主要工作城市是否有自有住房',finderYN,a.cityHousing)}${select('rentTier','主要工作城市租金扣除档',[[150000,'1500元/月'],[110000,'1100元/月'],[80000,'800元/月']],a.rentTier)}${monthPair('rent','住房租金')}`,'租金档位需按主要工作城市类别核对。')+
    finderPolicyBlock('首套住房贷款利息','政策项目 B','核对首套住房贷款利息、历史享受期限和夫妻分配方式。',`${select('loan','本人或配偶是否正在偿还首套住房贷款利息',finderYN,a.loan)}${select('loanShare','本人计划扣除比例',[[100,'100%'],[50,'50%']],a.loanShare)}${select('loanUsedMonths','历史已享受月数',Array.from({length:241},(_,i)=>[i,`${i}个月`]),a.loanUsedMonths)}${monthPair('loan','住房贷款')}`,'首套住房贷款利息每月1000元，最长240个月。')+
    finderPolicyBlock('互斥项目选择','决策确认','住房租金和住房贷款利息不能同时享受；两项均符合时请明确本年度选择。',`${select('housingChoice','两项都符合时本年度拟选择',[['undecided','尚未决定'],['rent','住房租金'],['loan','住房贷款利息']],a.housingChoice)}`)
  );
  return finderForm(
    4,'继续教育与大病医疗','先概括继续教育、资格证书和医疗自付情况，再按三类政策分别确认。',
    '简要说明是否接受学历继续教育、已享受月数，本年度是否取得职业资格证书，以及医保目录范围内个人自付金额与费用对象。例如：“正在读在职研究生，已享受12个月；今年取得职业资格证书；本人医疗自付2.8万元。”',
    finderPolicyBlock('学历（学位）继续教育','政策项目 A','核对境内学历教育状态、适用月份和同一学历已享受期限。',`${select('degree','是否正在接受境内学历（学位）继续教育',finderYN,a.degree)}${select('degreeUsedMonths','同一学历历史已享受月数',Array.from({length:49},(_,i)=>[i,`${i}个月`]),a.degreeUsedMonths)}${monthPair('degree','学历继续教育')}`,'学历继续教育每月400元，同一学历最长48个月。')+
    finderPolicyBlock('职业资格继续教育','政策项目 B','确认本年度是否取得技能人员或专业技术人员职业资格证书。',`${select('certificate','本年度是否取得符合目录的职业资格证书',finderYN,a.certificate)}`,'符合条件的职业资格证书在取得当年定额扣除3600元。')+
    finderPolicyBlock('大病医疗','政策项目 C','填写医保目录范围内、医保报销后的个人自付金额，并使用匿名对象标记。',`${select('medical','本年度是否有符合描述的大病医疗支出',finderYN,a.medical)}${field('medicalSelfPay','医保目录范围内个人自付金额',a.medicalSelfPay,'超过15000元的部分据实扣除，年度最高80000元。')}${field('medicalPerson','医疗费用对象标记',a.medicalPerson,'如本人、配偶、未成年子女A；无需填写真实姓名。','text')}`,'大病医疗通常在年度汇算环节核对，识别结果不能替代医疗票据和政策资格确认。')
  );
}
function monthlyChart(s,r){
  const max=Math.max(1,...r.rows.map(v=>v.take??0));
  return `<div class="chart">${r.rows.map((v,i)=>`<div class="barcol ${s.selected===i?'current':''}"><div class="bartrack"><div class="bar ${v.valid?'':'missingbar'}" title="${i+1}月 ${v.valid?yuan(v.take):'数据不齐'}" style="height:${v.valid?Math.max(1,(v.take??0)/max*100):4}%"></div></div><span>${i+1}月</span></div>`).join('')}</div><div class="legend"><span><i class="dot"></i>当前查看月份</span><span><i class="dot light"></i>含预测</span><span>空缺后累计结果暂停</span></div>`;
}
function contributionEditor(m){
  return `<h3 class="sectiontitle">个人社保与公积金</h3><p class="sub">比例已填入常用个人缴费默认值，可按当地政策和工资条修改。缴费基数留空时自动使用基本工资。</p><div class="formgrid" style="margin-top:18px">${optionalMoneyField('socialBase','社保缴费基数',m.socialBase,'留空时跟随本月基本工资；当地上下限需自行核对。')}${percentField('pensionRate','养老保险个人比例',m.pensionRate)}${percentField('medicalRate','医疗保险个人比例',m.medicalRate)}${percentField('unemploymentRate','失业保险个人比例',m.unemploymentRate)}${percentField('maternityRate','生育保险个人比例',m.maternityRate)}${percentField('injuryRate','工伤保险个人比例',m.injuryRate)}</div><div class="contribution-preview"><div><span>养老保险</span><b data-contribution-output="pension">${yuan(m.pension)}</b></div><div><span>医疗保险</span><b data-contribution-output="medical">${yuan(m.medical)}</b></div><div><span>失业保险</span><b data-contribution-output="unemployment">${yuan(m.unemployment)}</b></div><div><span>生育及工伤</span><b data-contribution-output="socialOther">${yuan(m.socialOther)}</b></div></div><div class="fund-config"><label class="switch-row"><input id="fundEnabled" name="fundEnabled" type="checkbox" ${m.fundEnabled?'checked':''}><span><b>缴纳住房公积金</b><small>关闭后本月个人住房公积金按0计算</small></span></label><div class="formgrid">${optionalMoneyField('fundBase','公积金缴费基数',m.fundBase,'留空时跟随本月基本工资。')}${percentField('fundRate','公积金个人比例',m.fundRate)}${field('fundExtra',names.fundExtra,m.fundExtra,'只填符合税前扣除范围的个人实际缴费。')}</div><div class="contribution-preview single"><div><span>住房公积金</span><b data-contribution-output="fund">${yuan(m.fund)}</b></div></div></div>`;
}
function monthly(s,r,step=1){
  const m=s.months[s.selected],v=r.rows[s.selected],d=deductionTotals(s.deductions),canResult=m.status!=='missing';
  const nav=`<div class="month-status-head"><div class="monthnav" aria-label="选择月份">${s.months.map((item,i)=>`<button data-month="${i}" class="status-${item.status} ${s.selected===i?'active':''}" title="${labels[item.status]}">${i+1}月</button>`).join('')}</div><div class="month-status-legend" aria-label="月份状态说明"><span><i class="status-dot actual"></i>已填写·已发生</span><span><i class="status-dot forecast"></i>已填写·预测</span><span><i class="status-dot missing"></i>未填写</span></div></div>`;
  const head=flowSteps(step,canResult,`${s.selected+1}月 · ${labels[m.status]}`);
  if(step===2&&canResult){
    const result=`<section class="panel result-page"><div class="result-hero"><div><span class="tag">${s.selected+1}月 · ${labels[m.status]}</span><div class="label">预计到手金额</div><div class="big">${yuan(v.take)}</div></div><button type="button" data-flow-step="1">← 返回修改</button></div><div class="result-columns"><div>${row('应税工资收入',yuan(v.gross))}${row('当月全年一次性奖金',yuan(v.bp))}${row('社保与公积金',yuan(v.cash))}${row('其他依法扣除',yuan(m.otherDeduct))}</div><div>${row('普通工资个税',yuan(v.tax))}${v.bonusTax?row('奖金单独计税税款',yuan(v.bonusTax)):''}${row('实际已录普通工资税款',m.status==='actual'?yuan(m.actualTax):'未发生')}${row('税后扣款＋养老金',yuan(m.after+m.pensionPay))}${row('报销／到账增加',yuan(m.reimburse))}</div></div>${v.valid?`<details open><summary>累计计税过程</summary><div class="result-columns"><div>${row('累计计税收入',yuan(v.inc))}${row('累计减除费用',yuan((s.selected+1)*500000))}${row('累计其他扣除及缴费',yuan(v.ded+v.pensionDed))}</div><div>${row('累计应纳税所得额',yuan(v.detail.base))}${row('税率 / 速算扣除',`${v.detail.rate}% / ${yuan(v.detail.quick)}`)}${row('累计应预扣税额',yuan(v.detail.amount))}${row('累计普通工资已扣税',yuan(v.cumulativeTax))}</div></div></details>`:'<div class="helper">本月或此前月份未填，或基准扣除待确认；暂停累计个税及到手计算。</div>'}${v.take!==null&&v.take<0?'<div class="error">预计到账为负，请核对输入。</div>':''}</section>`;
    return `${nav}${head}${result}<div style="margin-top:22px">${fundTable(s,r)}</div>`;
  }
  return `${nav}${head}<section class="panel flow-form"><div class="panelhead"><h2>${s.selected+1}月金额与扣除项目</h2>${tag(labels[m.status],m.status==='missing')}</div><form id="monthForm"><h3>收入信息</h3><div class="formgrid">${select('status','保存为',[['forecast','预测收入（0也表示已确认）'],['actual','已发生收入']],m.status==='missing'?'forecast':m.status)}${['salary','bonus','overtime','allowance','reduction'].map(k=>field(k,names[k],m[k])).join('')}</div>${contributionEditor(m)}<h3 class="sectiontitle">其他依法确定的扣除（可多选）</h3><p class="sub">按项目分别填写计税可扣金额；不要重复填写社保、公积金、专项附加扣除或个人养老金。若该笔支出还会减少工资到账，请同时在下方“其他税后扣款”记录实际现金影响。</p>${lawfulFields('',m.lawfulDeductions)}<h3 class="sectiontitle">专项附加扣除与到账调整</h3><div class="helper">本月台账预扣扣除：${yuan(d.monthly[s.selected])}。<button type="button" class="miniLink" data-tab="deductions">到台账维护</button> 专项附加扣除不再另填合计，避免重复。</div><div class="formgrid" style="margin-top:18px">${['pensionPay','after','reimburse'].map(k=>field(k,names[k],m[k],k==='pensionPay'?'按缴费当月在预扣环节享受模拟，年度上限12000元；不适用此口径时请使用年度精算。':'')).join('')}<div class="field"><label for="actualTax">实际工资条个税 / 元</label><input id="actualTax" name="actualTax" type="number" min="0" max="100000000" step="0.01" value="${m.actualTax===null?'':(m.actualTax/100).toFixed(2)}" placeholder="选填，留空使用预测"><small>只在已发生状态使用；仅填普通工资综合所得预扣税，不含单独计税奖金税款。</small></div></div><div class="submit-zone"><div><b>提交前会再次确认</b><span>确认后保存本月数据，并进入计算结果页。</span></div><div class="actions"><button class="primary" type="submit">确认并查看结果 →</button><button type="button" data-action="copy">复制到后续月份</button><button type="button" data-action="markMissing">标为未填写</button></div></div><p class="sub">保存全部0金额，表示确认该月0收入；未点击保存仍是未填写。复制不会覆盖已发生月份。</p></form></section>`;
}
function fundTable(s,r){
  const i=s.selected,keys=[...cashKeys,'tax','bonusTax','after','pensionPay'];
  const get=(j,k)=>s.months[j].status==='missing'?null:k==='tax'||k==='bonusTax'?r.rows[j].valid?r.rows[j][k]:null:s.months[j][k];
  const cum=k=>{const vs=Array.from({length:i+1},(_,j)=>get(j,k));return vs.includes(null)?null:total(vs);};
  const sumOrNull=vs=>vs.includes(null)?null:total(vs);
  return panel(`${i+1}月扣缴资金去向`,`<div class="tablewrap"><table><thead><tr><th>扣缴项目</th><th>当月金额</th><th>截至${i+1}月累计</th></tr></thead><tbody>${keys.map(k=>`<tr><td>${k==='tax'?'普通工资个人所得税':k==='bonusTax'?'单独计税奖金税款':names[k]}</td><td>${money(get(i,k))}</td><td>${money(cum(k))}</td></tr>`).join('')}<tr><td><b>个人扣缴及缴费总额</b></td><td>${money(sumOrNull(keys.map(k=>get(i,k))))}</td><td>${money(sumOrNull(keys.map(cum)))}</td></tr></tbody></table></div><p class="sub">累计含预测。个人养老金为个人账户缴费，不代表单位代扣。缺失数据用“—”展示，不按0累计。</p>`);
}
function quick(s,r,step=1){
  const q=s.quick,d=deductionTotals(s.deductions),fromMonths=q.source==='monthly',summary=r.sourceSummary;
  const missing=fromMonths?(summary?.missing??[]):[],canResult=q.confirmed&&missing.length===0;
  const quickNames={salary:'全年工资（不含全年一次性奖金）',cash:'全年个人社保及公积金',pensionPay:'本年个人养老金已有缴费',after:'全年其他税后扣款',reimburse:'全年非应税报销及到账增加'};
  const head=flowSteps(step,canResult,`${s.year}年度精算 · ${fromMonths?'月度汇总':'自行填写'}`);
  const sourceLawful=fromMonths?(summary?.lawfulDeductions??Object.fromEntries(lawfulKeys.map(k=>[k,0]))):q.lawfulDeductions;
  if(step===2&&canResult){
    const lawfulRows=lawfulKeys.filter(k=>sourceLawful[k]>0).map(k=>row(lawfulTypes[k].name,yuan(sourceLawful[k]))).join('')||row('其他依法扣除','¥ 0.00');
    const period=fromMonths?`1—${q.throughMonth}月月度汇总`:'全年自行填写';
    return `${head}<section class="panel result-page"><div class="result-hero"><div><span class="tag">${s.year}年度 · ${period}</span><div class="label">预计可支配现金</div><div class="big">${yuan(r.disposable)}</div></div><button type="button" data-flow-step="1">← 返回修改</button></div><div class="result-columns"><div>${row('工资及计入奖金',yuan(r.gross))}${row('个人社保及公积金',yuan(r.cash))}${row('专项附加扣除',yuan(r.special))}${row('个人养老金已有缴费',yuan(r.pensionActual))}${fromMonths?row('累计已扣税款',yuan(r.paid)):''}</div><div>${row('预计最终个税',yuan(r.finalTax))}${fromMonths?row('预计汇算差额',r.settlement===null?'待补齐':`${r.settlement>=0?'应补':'应退'} ${yuan(Math.abs(r.settlement))}`):''}${row('其他依法扣除合计',yuan(r.other))}${row('其他税后扣款',yuan(fromMonths?total(s.months.slice(0,q.throughMonth).filter(m=>m.status!=='missing').map(m=>m.after)):q.after))}${row('到账增加',yuan(fromMonths?total(s.months.slice(0,q.throughMonth).filter(m=>m.status!=='missing').map(m=>m.reimburse)):q.reimburse))}</div></div><details open><summary>其他依法扣除明细</summary>${lawfulRows}</details><div class="actions" style="margin-top:22px"><button class="primary" data-tab="planningSetup">继续比较个税方案 →</button><button data-tab="annual">查看年度记录</button></div><div class="helper">${fromMonths?`结果直接汇总1月至${q.throughMonth}月已填写记录，不覆盖月度数据，也不把后续月份补0或推算。后续收入变化后请重新测算。`:'结果按自行填写并确认的年度总额计算，不覆盖或反向生成月度记录。'} 测算仅供参考。</div></section>`;
  }
  const sourceChoices=`<div class="quick-source-grid"><label class="source-card ${fromMonths?'selected':''}"><input type="radio" name="quickSource" value="monthly" data-quick-source ${fromMonths?'checked':''}><span><b>从月度记录汇总</b><small>读取1月至截止月份的已填写数据，不要求覆盖全年，不改动月度记录。</small></span></label><label class="source-card ${fromMonths?'':'selected'}"><input type="radio" name="quickSource" value="manual" data-quick-source ${fromMonths?'':'checked'}><span><b>自行填写年度金额</b><small>适合没有逐月记录时使用；年度数据独立保存，不分摊到各月。</small></span></label></div>`;
  const monthSource=`<div class="source-panel"><div class="formgrid">${select('throughMonth','汇总截止月份',Array.from({length:12},(_,i)=>[i+1,`${i+1}月`]),q.throughMonth)}<div class="field source-stat"><label>已填写月份</label><strong>${summary?.filled??0} / ${q.throughMonth}个月</strong><small>已发生与预测均视为已填写。</small></div><div class="field source-stat"><label>截止月内缺失</label><strong class="${missing.length?'danger':'success'}">${missing.length?missing.join('、')+'月':'无'}</strong><small>缺失月份不会按0计算。</small></div></div><div class="cards compact source-summary">${card('累计税前收入',r.gross,`汇总至${q.throughMonth}月`,true)}${card('个人社保及公积金',r.cash,'来自月度已填写记录')}${card('其他依法扣除',r.other,'来自月度分类金额')}</div>${missing.length?`<div class="error">请先补齐截止月份内的${missing.join('、')}月，再生成结果；也可以把截止月份调整到连续已填的最后一个月。</div>`:'<div class="intro">截止月份内记录完整，可以直接汇总计算。后续月份保持未填写，不影响本次阶段测算。</div>'}</div>`;
  const manualSource=`<div class="source-panel"><h3>年度金额</h3><div class="formgrid">${Object.keys(quickNames).map(k=>field('q_'+k,quickNames[k],q[k])).join('')}</div><h3 class="sectiontitle">其他依法确定的扣除（可多选）</h3><p class="sub">按项目填写全年可扣金额，商业健康保险全年不超过2400元。</p>${lawfulFields('q_',q.lawfulDeductions,true)}</div>`;
  return `${head}${panel('第一页：选择取数方式并核对金额',`<form id="quickForm">${sourceChoices}${fromMonths?monthSource:manualSource}<div class="helper">全年一次性奖金：${yuan(s.bonus)} <button type="button" class="miniLink" data-tab="planningSetup">修改</button><br>已确认基准专项附加扣除：${yuan(d.baseline)} <button type="button" class="miniLink" data-tab="deductions">查看专项扣除申报台账</button></div>${check('quickConfirmed',fromMonths?`我已核对1月至${q.throughMonth}月的月度记录；已填写月份的数据可用于本次阶段测算。`:'我已核对自行填写的年度输入；填写0的项目已确认无金额。',q.confirmed)}<div class="submit-zone"><div><b>提交前会再次确认</b><span>确认后保存所选取数方式，并进入计算结果页。</span></div><button class="primary" type="submit">确认并查看结果 →</button></div></form><div class="helper">月度汇总适合已有逐月记录的情况；自行填写适合直接掌握年度合计的情况。两种方式均不会覆盖另一侧的原始数据。</div>`)}`;
}
function annual(s,r){
  if(s.mode==='quick')return panel('年度精算记录',`${row('工资及全年一次性奖金',yuan(r.gross))}${row('个人社保及公积金',yuan(r.cash))}${row('其他依法扣除',yuan(r.other))}${row('全年最终个税',yuan(r.finalTax))}${row('全年可支配现金',yuan(r.disposable))}<div class="actions" style="margin-top:18px"><button data-tab="quick">返回年度精算流程</button><button data-tab="planningSetup" class="primary">比较方案</button></div>`);
  return panel('十二个月，逐笔可查',`<div class="actions" style="margin-bottom:18px"><button data-action="csv">↓ 导出月度及累计扣缴明细</button></div><div class="tablewrap"><table><thead><tr><th>月份</th><th>状态</th><th>工资及奖金</th><th>个人缴费</th><th>普通工资个税</th><th>奖金单独税</th><th>累计普通工资税</th><th>预计到手</th></tr></thead><tbody>${r.rows.map((v,i)=>`<tr><td><button class="miniLink" data-month="${i}">${i+1}月 ↗</button></td><td>${tag(labels[s.months[i].status],s.months[i].status!=='actual')}</td><td>${s.months[i].status==='missing'?'—':money(v.gross+v.bp)}</td><td>${s.months[i].status==='missing'?'—':money(v.cash)}</td><td>${money(v.tax)}${s.months[i].status==='actual'&&s.months[i].actualTax===null?'<small>（预测）</small>':''}</td><td>${v.valid?money(v.bonusTax):'—'}</td><td>${money(v.cumulativeTax)}</td><td><b>${money(v.take)}</b></td></tr>`).join('')}</tbody></table></div><div class="helper">基准奖金方式：${s.currentBonusMode==='combined'?'并入综合所得':'单独计税'}。已发生但未填实际工资税款的月份，仍使用系统预测。缺失月份及其后累计税额不输出。</div>`);
}
function deductions(s,r,edit){
  const d=deductionTotals(s.deductions);
  const table=panel('专项扣除申报台账',`<div class="cards compact">${card('已确认基准扣除',d.baseline,'计入当前基准')}${card('已确认新增扣除',d.proposed,'仅在备选组合中使用')}${card('待确认项目数',(d.pendingBaseline+d.pendingProposed)*100,'不进入正式计算')}</div><div class="actions" style="margin-bottom:18px"><button class="primary" data-action="addDed">＋ 新增扣除项目</button></div>${s.deductions.length?`<div class="tablewrap"><table><thead><tr><th>项目 / 对象</th><th>月份</th><th>年度可用金额</th><th>用途</th><th>环节</th><th>状态</th><th>操作</th></tr></thead><tbody>${s.deductions.map(x=>`<tr><td>${TYPES[x.type].name}<br><span class="muted">${esc(x.person)}</span></td><td>${TYPES[x.type].annual?'年度':x.start+'—'+x.end+'月'}</td><td>${x.confirmed?money(deductionValue(x)):'待确认'}${x.type==='legacy'?`<br><small>原金额 ${money(x.amount)}${x.timing==='withholding'?'/月':'/年'}</small>`:''}</td><td>${x.usage==='baseline'?'基准已有':'备选新增'}</td><td>${x.timing==='annual'?'仅年度汇算':'工资预扣＋年度'}</td><td>${tag(x.confirmed?'已确认':'待确认',!x.confirmed)}</td><td><button class="miniLink" data-edit-ded="${esc(x.id)}">编辑</button> <button class="miniLink" data-delete-ded="${esc(x.id)}">删除</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">暂无项目。若确实没有可用扣除，可保持空台账；无需填0项目。</div>'}<div class="helper">台账记录的是个人可扣金额，不是实际现金支出。未确认基准扣除会暂停全年结果；未确认备选只提示，不参加比较。住房互斥、重叠月份和额度由系统检查，真实资格仍需你核对。</div>`);
  return `${table}${edit?`<div style="margin-top:22px">${dedEditor(edit)}</div>`:''}${policyPanel()}`;
}
function dedEditor(d){
  const meta=TYPES[d.type],monthOpts=Array.from({length:12},(_,i)=>[i+1,`${i+1}月`]);
  return panel('编辑扣除项目',`<form id="dedForm" data-id="${esc(d.id)}"><div class="formgrid">${select('d_type','扣除项目',Object.entries(TYPES).filter(([k])=>k!=='legacy'||d.type==='legacy').map(([k,v])=>[k,v.name]),d.type)}${field('d_person',meta.person?'对象标记（如孩子A，无需实名）':'对象标记',d.person,'同一对象保持相同标记，便于检查重复。','text')}${select('d_usage','计入方案',[['baseline','基准已有扣除'],['proposed','备选新增扣除']],d.usage)}${select('d_timing','使用环节',(meta.annual||d.usage==='proposed')?[['annual','仅年度汇算']]:[['withholding','工资预扣＋年度汇算'],['annual','仅年度汇算']],d.timing)}${!meta.annual?select('d_start','适用起始月份',monthOpts,d.start)+select('d_end','适用结束月份',monthOpts,d.end):''}${field('d_amount',d.type==='medical'?'该对象年度医保目录内自付额':meta.annual?'个人年度可扣金额':'个人每月可扣金额',d.amount)}${['child','baby','loan'].includes(d.type)?select('d_share','个人分配比例',[[100,'100%'],[50,'50%']],d.share):''}${d.type==='rent'?select('d_rentTier','主要工作城市扣除档',[[150000,'1500元/月'],[110000,'1100元/月'],[80000,'800元/月']],d.rentTier):''}${d.type==='elder'?select('d_sole','是否独生子女',[['yes','是：每月最高3000元'],['no','否：每月最高1500元']],d.sole?'yes':'no'):''}</div><div class="helper">${meta.help}${d.usage==='proposed'?'<br>备选新增扣除统一按年度汇算模拟，不修改月度已扣税。':''}</div>${check('d_confirmed','我已核对项目资格、适用月份、分配及历史期限；个人金额未在其他项目、其他依法扣除或家庭成员重复申报。',d.confirmed)}${d.type==='legacy'?'<div class="error">请先选择具体扣除项目。若原合计含多项，请分别建项，完成后再移除旧合计。</div>':''}<div class="actions" style="margin-top:16px"><button class="primary" type="submit">保存项目并校验</button><button type="button" data-action="cancelDed">取消编辑</button></div></form>`);
}
function planningStage(active){
  return `<section class="planning-stage"><div><span class="eyebrow">个税筹划与设计</span><b>两步完成方案比较</b><small>比较条件与结论分开保存和查看，修改条件后结论会同步重算。</small></div><div class="planning-stage-steps"><button data-tab="planningSetup" class="${active==='setup'?'active':''}"><i>1</i><span>设置比较条件<small>奖金、预算与目标</small></span></button><b></b><button data-tab="planningResults" class="${active==='results'?'active':''}"><i>2</i><span>筹划结论查看<small>差异、理由与执行项</small></span></button></div></section>`;
}
function planningSetup(s,r){
  const d=deductionTotals(s.deductions);
  const input=panel('设置比较条件',`<form id="planForm"><div class="formgrid">${field('annualBonus','全年一次性奖金',s.bonus,'不含已录入工资中的普通奖金；不拆分已发的一笔奖金。')}${select('bonusMonth','预计取得月份',Array.from({length:12},(_,i)=>[i+1,`${i+1}月`]),s.bonusMonth)}${field('pensionPlan','计划新增养老金预算',s.pensionPlan,'最高12000元；扣除已有缴费后，按剩余额度计算。')}${select('currentBonusMode','当前基准计税方式',s.bonusEligible?[['combined','并入综合所得'],['separate','单独计税']]:[['combined','并入综合所得']],s.currentBonusMode)}${select('goal','比较目标',[['cash','全年可支配现金较高'],['tax','全年最终税款较低']],s.goal)}</div>${check('bonusEligible','我确认该笔奖金符合全年一次性奖金条件，当年未对其他奖金使用单独计税，取得年度在有效期内。',s.bonusEligible)}<div class="helper">基准扣除 ${yuan(d.baseline)}；备选新增扣除 ${yuan(d.proposed)}；待确认备选 ${d.pendingProposed}项（不计入比较）。<button type="button" class="miniLink" data-tab="deductions">维护专项扣除申报台账</button></div><div class="submit-zone"><div><b>保存后自动生成比较结论</b><span>系统将重新计算奖金计税、可用新增扣除与养老金预算的全部组合。</span></div><button class="primary" type="submit">保存条件并查看结论 →</button></div></form>`);
  const context=panel('本次比较范围',`${row('当前数据完整度',r.complete?'已满足比较条件':'仍有资料待补齐')}${row('全年收入基础',yuan(r.gross))}${row('基准专项附加扣除',yuan(d.baseline))}${row('备选新增扣除',yuan(d.proposed))}${row('比较目标',s.goal==='tax'?'全年最终税款较低':'全年可支配现金较高')}<div class="helper">比较只覆盖当前工具支持的组合。建议先确认收入记录和专项扣除台账，再保存条件。</div><div class="actions" style="margin-top:16px"><button data-tab="annual">核对年度记录</button><button data-tab="deductions">核对申报台账</button></div>`);
  return `<div class="stack">${planningStage('setup')}<div class="grid planning-setup-grid">${input}${context}</div>${policyPanel()}</div>`;
}
function planningResults(s,r){
  const list=plans(s),ranked=rankPlans(list,s.goal),best=ranked[0];
  const result=!best?panel('方案比较尚未就绪',`<div class="empty">补齐年度数据、确认基准扣除及适用范围后，再生成可用方案。</div><div class="actions planning-empty-actions"><button class="primary" data-tab="planningSetup">返回设置比较条件</button><button data-tab="annual">核对年度记录</button></div>`):recommendation(s,list,ranked);
  return `<div class="stack">${planningStage('results')}${result}${best?cliffPanel(s,r):''}${policyPanel()}</div>`;
}
function recommendation(s,list,ranked){
  const best=ranked[0],byTax=rankPlans(list,'tax')[0],byCash=rankPlans(list,'cash')[0];
  const tied=ranked.filter(x=>s.goal==='tax'?x.finalTax===best.finalTax:x.disposable===best.disposable);
  const instruction=[best.mode!==s.currentBonusMode?'核对奖金资格并选择对应计税方式':'保留当前奖金计税方式',best.extra?'将台账中全部已确认“备选新增扣除”按条件纳入年度汇算':'不新增台账扣除',best.addedPension?`在已录缴费之外新增个人养老金 ${yuan(best.addedPension)}，确认资金安排及凭证`:'不新增养老金缴费'];
  return panel(s.demo?'示例情景比较（不作为个人推荐）':'当前条件下的比较结论',`<div class="intro"><h3>${best.name}</h3>当前目标：${s.goal==='tax'?'全年税款较低':'全年可支配现金较高'}。相比基准预计少缴税 <b>${yuan(best.saving)}</b>，可支配现金变化 <b>${best.cashChange>=0?'+':'−'}${yuan(Math.abs(best.cashChange))}</b>。${tied.length>1?`有${tied.length}个方案在当前目标上并列，优先展示改变事项较少、追加缴费较少的方案。`:''}</div><div class="checklist"><div class="checkitem"><b>税款最低</b>${esc(byTax.name)}<br>${yuan(byTax.finalTax)} / 年</div><div class="checkitem"><b>可支配现金最高</b>${esc(byCash.name)}<br>${yuan(byCash.disposable)} / 年</div></div><h3 class="sectiontitle">为什么选择它，执行前需要做什么？</h3><ol class="reasonList">${instruction.map(x=>`<li>${x}</li>`).join('')}</ol><p class="sub">已比较${list.length}个有效组合：奖金方式 × 是否使用全部已确认新增扣除 × 是否追加预算内养老金。预测收入、资格或金额改变，结论随之变化。</p><div class="tablewrap" style="margin-top:18px"><table><thead><tr><th>方案</th><th>最终个税</th><th>比基准少缴税</th><th>新增支出／受限资金</th><th>可支配现金</th><th>改动项数</th></tr></thead><tbody>${ranked.map(p=>`<tr class="${p.id===best.id?'selectedRow':''}"><td>${esc(p.name)} ${p.id==='base'?tag('当前基准'):''}</td><td>${money(p.finalTax)}</td><td>${money(p.saving)}</td><td>${money(p.addedPension)}</td><td><b>${money(p.disposable)}</b></td><td>${p.changes}</td></tr>`).join('')}</tbody></table></div><details><summary>展开较优方案计算明细</summary>${row('全年收入',yuan(best.gross))}${row('个人社保及公积金',yuan(best.cash))}${row('基准专项附加扣除',yuan(best.special))}${row('本方案新增专项附加扣除',yuan(best.extra))}${row('其他依法扣除',yuan(best.other))}${row('养老金已有＋新增缴费',yuan(best.pensionActual+best.addedPension))}${row('年度综合所得应纳税所得额',yuan(best.annual.base))}${row('综合所得税款',yuan(best.annual.amount))}${row('奖金单独计税税款',yuan(best.bonusTax))}</details><div class="helper">只在当前输入和支持的组合中比较，不代表全部筹划方式的全局最优。养老金新增支出与新增受限资金是同一笔款，只扣一次；未预测未来收益及领取税款。普通收入同年调整发放月份，不视为年度节税。</div>`);
}
function cliffPanel(s,r){
  const curve=bonusCurve(s.bonus,r.annualIncomeBase),points=curve.points;
  const minY=Math.min(...points.map(p=>p.net),...(r.complete?points.map(p=>p.combined):[])),maxY=Math.max(...points.map(p=>p.net),...(r.complete?points.map(p=>p.combined):[]));
  const px=x=>55+(x-curve.min)/(curve.max-curve.min)*625,py=y=>205-(y-minY)/Math.max(1,maxY-minY)*175;
  const path=k=>points.map((p,i)=>`${i?'L':'M'}${px(p.amount).toFixed(2)},${py(p[k]).toFixed(2)}`).join(' ');
  const t=curve.nearest,delta=curve.plusOne.net-curve.at.net;
  return panel('奖金临界点 · 看税后变化',`<p class="sub">独立假设曲线，不是拆分建议。横轴为奖金税前金额，纵轴为该笔奖金带来的税后增加；绿色为单独计税，灰色为并入后的增量（需全年数据完整）。</p><svg class="taxcurve" viewBox="0 0 730 260" role="img" aria-label="奖金金额与税后奖金关系曲线"><path d="M55 25V215H690" fill="none" stroke="#dce5e7"/><path d="${path('net')}" fill="none" stroke="#187b69" stroke-width="3"/>${r.complete?`<path d="${path('combined')}" fill="none" stroke="#8a99a5" stroke-width="2" stroke-dasharray="6 4"/>`:''}<line x1="${px(t)}" y1="25" x2="${px(t)}" y2="215" stroke="#d39452" stroke-dasharray="4 4"/><circle cx="${px(s.bonus)}" cy="${py(curve.at.net)}" r="5" fill="#187b69"/><text x="55" y="240">${money(curve.min)}</text><text x="570" y="240">${money(curve.max)} 元奖金</text><text x="55" y="17">税后增加（元）</text><text x="${Math.min(540,Math.max(60,px(t)+8))}" y="38">临界 ${money(t)}</text></svg><div class="checklist"><div class="checkitem"><b>当前奖金 ${yuan(s.bonus)}</b>单独计税后 ${yuan(curve.at.net)}<br>奖金多1元，税后变化 <span class="${delta<0?'danger':'success'}">${delta<0?'−':'+'}${yuan(Math.abs(delta))}</span></div><div class="checkitem"><b>最近临界点 ${yuan(t)}</b>以下按临界点前后0.01元精确比较，不建议为卡档任意改变已发收入。</div></div><div class="tablewrap" style="margin-top:18px"><table><thead><tr><th>奖金税前金额</th><th>单独计税税额</th><th>单独计税后奖金</th></tr></thead><tbody>${[t-1,t,t+1,t+100].map(x=>`<tr><td>${money(x)}</td><td>${money(bonusTax(x))}</td><td>${money(x-bonusTax(x))}</td></tr>`).join('')}</tbody></table></div><div class="helper">${s.bonusEligible?'已确认单独计税资格。':'单独计税资格未确认，曲线仅演示公式，不加入推荐。'}${r.complete?'':' 年度数据未齐，暂停显示并入综合所得的税后增量曲线。'} 图形精度受像素限制，以0.01元边界表为准。政策有效期至2027年12月31日。</div>`);
}
function settings(s,accountName=''){return `<div class="stack">${panel('本机账号与密码',`<div class="account-summary"><div><span>当前本机账号</span><strong>${esc(accountName)}</strong></div><button data-action="logout">退出当前账号</button></div><form id="changePasswordForm"><div class="formgrid password-grid"><div class="field"><label for="currentPassword">当前密码</label><input id="currentPassword" name="currentPassword" type="password" minlength="8" maxlength="128" autocomplete="current-password" required></div><div class="field"><label for="newPassword">新密码</label><input id="newPassword" name="newPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required><small>至少8个字符。</small></div><div class="field"><label for="confirmPassword">再次输入新密码</label><input id="confirmPassword" name="confirmPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></div></div><button class="primary" type="submit" style="margin-top:16px">修改密码</button></form><div class="helper">这是当前浏览器的本机访问锁，不需要 GPT 或 GitHub 账号。密码校验值经过加盐处理，但工资数据本身未加密，也不会跨设备同步。当前版本不提供密码找回，请先导出备份并牢记密码。</div>`)}${panel('适用范围确认',`${check('scope','我是中国内地居民个人，本年度从1月起在同一单位任职；测算只涉及普通工资薪金及符合条件的全年一次性奖金，不含未支持收入或特殊预扣优惠。',s.scope)}<div class="helper">暂不支持换工作、多单位、劳务报酬、境外与经营所得、特殊预扣、减免税、低收入免办汇算判断。实际扣税与模型可能因这些原因不同。</div>`)}${panel('本机数据管理',`<p class="sub">记录仅保存在当前浏览器。年度精算与月度输入分别保存；奖金和专项扣除申报台账共用。切换不会覆盖另一种模式的数据。</p><div class="actions" style="margin-top:20px"><button class="primary" data-action="backup">↓ 导出完整备份</button><button data-action="import">↑ 导入备份</button><button data-action="csv">导出当前模式 CSV</button><button data-action="start">清空当前年度重新开始</button>${s.migrationNotice?'<button data-action="oldBackup">下载旧版快照</button>':''}</div><input type="file" id="importFile" accept="application/json,.json" hidden><div class="helper">导入会校验版本、金额和扣除冲突，确认后仅替换相同年度。旧版合计扣除需重新分类；原数据快照在迁移前保存。请定期备份，浏览器清理会丢失本地记录。</div>`)}${policyPanel()}</div>`;}
export function policyPanel(){return panel('政策依据与范围',`<div class="policylist"><a target="_blank" rel="noopener" href="https://shanghai.chinatax.gov.cn/zcfw/zcjd/201812/t443220.html">居民工资薪金累计预扣法及税率表 ↗</a><a target="_blank" rel="noopener" href="https://www.chinatax.gov.cn/n810219/n810744/n3752930/n3752974/c3963364/content.html">依法确定的其他扣除法定类别 ↗</a><a target="_blank" rel="noopener" href="https://www.chinatax.gov.cn/chinatax/n810341/n810765/n812146/n812300/c1079953/content.html">企业年金、职业年金个人缴费扣除口径 ↗</a><a target="_blank" rel="noopener" href="https://shenzhen.chinatax.gov.cn/sztax/zcwj/rdwd/202506/e9af4e54cabf47a2bf4e909f447e1af2.shtml">商业健康保险：每月200元、全年2400元限额 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c102416/c5211524/content.html">全年一次性奖金：符合条件可选单独计税或并入，执行至2027年12月31日 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c102416/c5237110/content.html">个人养老金：年度扣除限额12000元，未来领取另有税务规则 ↗</a><a target="_blank" rel="noopener" href="https://www.chinatax.gov.cn/chinatax/n810219/n810744/n3752930/n3752974/c3963375/content.html">专项附加扣除：资格、环节、额度与互斥条件 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c100012/c5213592/content.html">婴幼儿、子女教育及赡养老人扣除标准更新 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c100024/c5237602/content.html">大病医疗：超过15000元部分、年度限额80000元 ↗</a></div><p class="sub" style="margin-top:15px">支持2026、2027年度。政策核对日期2026-10-22。扣除未自动核验真实资格，输入需与凭证、家庭分配及税务记录一致。</p>`);}
